from lc import L, w, gr, q

B2 = [
 L("What Happens When We Sleep", "睡覺時身體在做什麼", [
   "Most adults need between seven and nine hours of sleep a night, yet many regularly get far less. Sleep is not simply a pause in our day. While we rest, the brain moves through several stages, including REM sleep, when most vivid dreaming takes place.",
   "These stages play an important role in memory. During deep sleep, the brain appears to strengthen the connections formed during the day, which helps us hold on to new information. Missing out on sleep, on the other hand, can affect our mood, our concentration and even our appetite.",
   "One common obstacle is screen time before bed. Bright light from phones can delay the release of melatonin, a hormone that tells the body it is time to sleep. Experts suggest keeping a regular bedtime and switching devices off well before you turn out the light."],
  [w("regularly","adverb","/ˈreɡ.jə.lɚ.li/","經常地、定期地","often, or at the same time each day or week","I regularly go running.","regular + -ly，修飾動詞 get。"),
   w("stage","noun","/steɪdʒ/","階段","a part of a process","the early stages of the project","several stages 幾個階段（可數）。"),
   w("vivid","adjective","/ˈvɪv.ɪd/","生動的、鮮明的","very clear and detailed","I had a vivid dream.","vivid dreaming 鮮明的夢境。"),
   w("strengthen","verb","/ˈstreŋ.θən/","加強","to make something stronger","Exercise strengthens muscles.","strength + -en 變動詞。"),
   w("concentration","noun","/ˌkɑːn.sənˈtreɪ.ʃən/","專注力","the ability to think carefully about one thing","Noise affects my concentration.","concentrate 的名詞，不可數。"),
   w("obstacle","noun","/ˈɑːb.stə.kəl/","障礙","something that makes it difficult to do something","Cost is the main obstacle.","an obstacle to + 名詞。"),
   w("hormone","noun","/ˈhɔːr.moʊn/","荷爾蒙","a chemical in the body that controls how it works","Stress hormones rise when we are afraid.","a hormone that… 關係子句說明功能。")],
  [gr("yet 表轉折","yet 連接兩個子句，意思像 but。","Most adults need between seven and nine hours of sleep a night, yet many regularly get far less."),
   gr("appear to + V","似乎…，語氣比較保留。","the brain appears to strengthen the connections formed during the day"),
   gr("on the other hand","另一方面，用來對比。","Missing out on sleep, on the other hand, can affect our mood")],
  [q("What usually happens during REM sleep?","Most vivid dreaming","The body stops breathing","We wake up every few minutes"),
   q("Why is deep sleep important for learning?","It helps the brain keep new information","It makes us forget bad memories","It increases our appetite"),
   q("How can phone light affect sleep?","It can delay a sleep hormone","It makes us sleep too long","It improves our dreams")]),
 L("The Secret Life of a Bee Colony", "蜂群的祕密生活", [
   "A honey bee colony works like a small, well-organized city. Each hive usually has one queen, whose main job is to lay eggs, along with thousands of female worker bees and a smaller number of males called drones.",
   "Worker bees take on different tasks as they get older, from cleaning the hive to collecting nectar and pollen. When a bee finds a good source of food, it returns home and performs a \"waggle dance\" that tells the others which direction to fly and roughly how far to go.",
   "Bees matter far beyond the hive. By carrying pollen from flower to flower, they pollinate many of the fruits and vegetables we eat. However, bee populations face serious threats, including pesticides, parasites and the loss of the wild flowers they depend on."],
  [w("colony","noun","/ˈkɑː.lə.ni/","群落（蜂群、蟻群）","a group of the same type of animal living together","an ant colony","a honey bee colony 一個蜂群。"),
   w("organized","adjective","/ˈɔːr.ɡə.naɪzd/","有組織的","arranged in a clear and effective way","a well-organized team","well-organized 複合形容詞。"),
   w("nectar","noun","/ˈnek.tɚ/","花蜜","a sweet liquid made by flowers","Bees drink nectar.","不可數名詞。"),
   w("roughly","adverb","/ˈrʌf.li/","大約","approximately; not exactly","roughly 100 people","= about；放在數字或程度前。"),
   w("pollinate","verb","/ˈpɑː.lə.neɪt/","授粉","to carry pollen to a flower so it can make seeds","Insects pollinate crops.","pollen（花粉）→ pollinate。"),
   w("pesticide","noun","/ˈpes.tə.saɪd/","殺蟲劑","a chemical used to kill insects that harm crops","Some pesticides harm bees.","複數 pesticides。"),
   w("depend on","phrasal verb","/dɪˈpend ɑːn/","依賴","to need someone or something","Children depend on their parents.","the flowers they depend on 介系詞留在句尾。")],
  [gr("whose 所有格關係代名詞","whose main job = the queen's main job。","one queen, whose main job is to lay eggs"),
   gr("from A to B 表範圍","列舉從簡單到複雜的工作。","from cleaning the hive to collecting nectar and pollen"),
   gr("By + V-ing","藉由…（方法）。","By carrying pollen from flower to flower, they pollinate many of the fruits and vegetables we eat.")],
  [q("What is the queen's main job?","Laying eggs","Collecting nectar","Guarding the hive"),
   q("What does the waggle dance tell other bees?","Where food is and how far it is","That the queen is sick","When to sleep"),
   q("Which is NOT mentioned as a threat to bees?","Cold winters","Pesticides","Parasites")]),
 L("Why Most Plastic Is Never Recycled", "為什麼大部分塑膠沒有被回收", [
   "We often throw plastic bottles into the recycling bin and assume the problem is solved. In reality, only a small share of all the plastic ever produced has been recycled. Much of it ends up in landfills, is burned, or leaks into rivers and oceans.",
   "Part of the difficulty is that plastic comes in many different types. Items are usually marked with a number from one to seven. Bottles made of PET (number 1) and containers made of HDPE (number 2) are the easiest to recycle, while many others are rarely accepted.",
   "Dirty or mixed materials cause further problems, because food waste can contaminate a whole batch. Even when plastic is recycled, it is often turned into lower-quality products. That is why many experts argue that using less plastic in the first place matters most."],
  [w("assume","verb","/əˈsuːm/","以為、假定","to think something is true without proof","Don't assume he knows.","assume (that) + 子句。"),
   w("share","noun","/ʃer/","一部分、份額","a part of a total amount","a large share of the market","a small share of… …的一小部分。"),
   w("landfill","noun","/ˈlænd.fɪl/","垃圾掩埋場","a place where waste is buried under the ground","The rubbish goes to a landfill.","複數 landfills。"),
   w("leak","verb","/liːk/","滲漏、流入","to escape through a hole or gap","Oil leaked into the sea.","leak into + 地方。"),
   w("rarely","adverb","/ˈrer.li/","很少","not often","He rarely eats meat.","頻率副詞，放在 be 動詞後。"),
   w("contaminate","verb","/kənˈtæm.ə.neɪt/","污染","to make something dirty or harmful","Chemicals contaminated the water.","名詞 contamination。"),
   w("argue","verb","/ˈɑːrɡ.juː/","主張","to give reasons for an opinion","She argues that taxes should fall.","argue that + 子句：主張…。")],
  [gr("被動語態 be marked with","物品被標上…。","Items are usually marked with a number from one to seven."),
   gr("while 表對比","while 連接兩個對比的情況。","while many others are rarely accepted"),
   gr("in the first place","一開始就…、從源頭。","using less plastic in the first place matters most")],
  [q("What happens to much plastic waste?","It goes to landfills or is burned","It is all recycled","It disappears quickly"),
   q("Which plastics are easiest to recycle?","Numbers 1 and 2","Numbers 6 and 7","All types equally"),
   q("What do many experts think matters most?","Using less plastic to begin with","Building more landfills","Burning plastic safely")]),
 L("Thirty Days to Try Something New", "用 30 天嘗試新事物", [
   "In his short TED talk, Google engineer Matt Cutts describes a simple idea that changed his life. Feeling stuck in a routine, he decided to try something new for 30 days. Thirty days, he explains, is just about the right amount of time to add a new habit or remove an old one.",
   "The experiments ranged from biking to work to taking a picture every day. Over time, he noticed that the months became far more memorable. His self-confidence grew too, and he eventually climbed Mount Kilimanjaro and wrote a novel of 50,000 words in a single month.",
   "Cutts also observes that small, sustainable changes are more likely to stick than big, dramatic ones. His challenge to the audience is easy to accept: think of something you have always wanted to try, and give it the next 30 days."],
  [w("stuck","adjective","/stʌk/","卡住的、停滯的","unable to move or change","I feel stuck in my job.","stick 的過去分詞當形容詞。"),
   w("routine","noun","/ruːˈtiːn/","例行公事","the usual order in which you do things","a morning routine","stuck in a routine 一成不變。"),
   w("range","verb","/reɪndʒ/","範圍涵蓋","to include different things between two limits","Prices range from $5 to $50.","range from A to B。"),
   w("memorable","adjective","/ˈmem.ɚ.ə.bəl/","難忘的","easy to remember because special","a memorable trip","memory → memorable。"),
   w("eventually","adverb","/ɪˈven.tʃu.ə.li/","最後、終於","in the end, after a long time","He eventually found a job.","常放在動詞前。"),
   w("sustainable","adjective","/səˈsteɪ.nə.bəl/","可持續的","able to continue for a long time","a sustainable diet","sustain + -able。"),
   w("stick","verb","/stɪk/","持續、保持下去","to continue to exist or be used","The nickname stuck.","文中 stick = 習慣留下來。")],
  [gr("分詞構句 Feeling…","Feeling stuck = Because he felt stuck。","Feeling stuck in a routine, he decided to try something new for 30 days."),
   gr("be likely to + V","可能會…。","small, sustainable changes are more likely to stick than big, dramatic ones"),
   gr("插入語 he explains","插在句中說明是誰說的。","Thirty days, he explains, is just about the right amount of time")],
  [q("Why did Cutts start his 30-day challenges?","He felt stuck in a routine","His boss told him to","He was bored of Google"),
   q("Which of these did he achieve?","Writing a 50,000-word novel","Running a marathon in Asia","Learning ten languages"),
   q("What kind of changes are more likely to last?","Small, sustainable ones","Big, dramatic ones","Expensive ones")]),
]

C1 = [
 L("The Hidden Work of a Sleeping Brain", "大腦在睡眠中默默做的事", [
   "Sleep is easily dismissed as wasted time, yet the brain is anything but idle at night. Over the course of a typical night, it cycles several times through distinct stages, from light and deep non-REM sleep to REM sleep, the phase most closely associated with vivid dreaming.",
   "Each stage appears to serve a purpose. Deep sleep is thought to consolidate memories, transferring fragile new information into more durable storage, while REM sleep may help us process emotions. Cut these cycles short, and the effects quickly surface in poorer attention, irritability and impaired judgment.",
   "Chronic sleep loss carries subtler costs as well. It has been linked to changes in the hormones that regulate hunger, which may partly explain why tired people crave sugary food, and to a weaker immune response.",
   "Modern habits rarely help. Exposure to bright screens late in the evening can suppress melatonin and push back the body's internal clock. The remedy is unglamorous but effective: a consistent schedule, a dark and quiet bedroom, and a firm cut-off time for devices."],
  [w("dismiss","verb","/dɪˈsmɪs/","不予理會、視為不重要","to decide something is not important","He dismissed the idea as silly.","be dismissed as… 被看作…。"),
   w("idle","adjective","/ˈaɪ.dəl/","閒置的、不活動的","not working or active","The machines stood idle.","anything but idle 一點也不閒。"),
   w("consolidate","verb","/kənˈsɑː.lə.deɪt/","鞏固","to make something stronger and more lasting","consolidate your knowledge","consolidate memories 鞏固記憶。"),
   w("fragile","adjective","/ˈfrædʒ.əl/","脆弱的","easily broken or damaged","fragile glass","fragile new information 尚不穩固的新資訊。"),
   w("impaired","adjective","/ɪmˈperd/","受損的","damaged or not working well","impaired hearing","impair 的過去分詞當形容詞。"),
   w("crave","verb","/kreɪv/","渴望","to want something very strongly","I crave chocolate.","crave + 名詞。"),
   w("suppress","verb","/səˈpres/","抑制","to stop something from happening or growing","The drug suppresses pain.","suppress melatonin 抑制褪黑激素。"),
   w("unglamorous","adjective","/ʌnˈɡlæm.ɚ.əs/","平淡無奇的","not exciting or attractive","an unglamorous job","un- + glamorous。")],
  [gr("anything but","一點也不…。","the brain is anything but idle at night"),
   gr("祈使句 + and 表條件","Cut… and… = 如果縮短…，就會…。","Cut these cycles short, and the effects quickly surface"),
   gr("which may partly explain why","用 which 指前句，帶出解釋。","which may partly explain why tired people crave sugary food")],
  [q("What is the writer's main point in the first paragraph?","The brain stays busy during sleep","Sleep is mostly wasted time","Dreams only happen in deep sleep"),
   q("According to the text, what might deep sleep do?","Turn new information into lasting memories","Increase hunger hormones","Make us more irritable"),
   q("How does the writer describe the solution?","Simple and not exciting, but it works","Expensive and complicated","Only useful for children")]),
 L("How a Hive Thinks Without a Leader", "沒有領袖的蜂巢如何做決定", [
   "It is tempting to imagine the queen as the ruler of a honey bee colony, but she gives no orders. Her role is chiefly reproductive. The daily running of the hive emerges instead from the actions of tens of thousands of workers, each responding to simple signals from its surroundings.",
   "The division of labor is strikingly flexible. Young workers tend the brood and build wax comb; older ones graduate to foraging. Foragers that locate a rich patch of flowers communicate its position through the waggle dance, encoding direction relative to the sun and distance in the length of each run.",
   "The ecological stakes are considerable. Bees pollinate a large proportion of the crops humans rely on, from almonds to apples, so a decline in their numbers reverberates through the food system.",
   "That decline is not driven by a single culprit. Pesticides, parasitic mites, disease and the disappearance of wildflower habitats all combine to weaken colonies, which is why protecting bees calls for changes in farming, not just in beekeeping."],
  [w("tempting","adjective","/ˈtemp.tɪŋ/","誘人的","making you want to do something","It's tempting to stay in bed.","It is tempting to + V 很容易想要…。"),
   w("chiefly","adverb","/ˈtʃiːf.li/","主要地","mainly","The book is chiefly about love.","= mainly。"),
   w("emerge","verb","/ɪˈmɝːdʒ/","浮現、產生","to appear or develop","A pattern emerged.","emerge from… 從…中產生。"),
   w("strikingly","adverb","/ˈstraɪ.kɪŋ.li/","驚人地、顯著地","in a way that is very noticeable","strikingly beautiful","放在形容詞前加強語氣。"),
   w("forage","verb","/ˈfɔːr.ɪdʒ/","覓食","to search for food","Bees forage for nectar.","forager 覓食者。"),
   w("stake","noun","/steɪk/","利害關係","something that could be won or lost","The stakes are high.","the stakes are considerable 影響重大。"),
   w("reverberate","verb","/rɪˈvɝː.bə.reɪt/","產生廣泛影響","to have a strong effect that spreads widely","The news reverberated around the world.","reverberate through… 影響遍及…。"),
   w("culprit","noun","/ˈkʌl.prɪt/","罪魁禍首","the cause of a problem","Sugar is the main culprit.","a single culprit 單一元兇。")],
  [gr("It is tempting to…","形式主詞 it，真正主詞是 to 不定詞。","It is tempting to imagine the queen as the ruler of a honey bee colony"),
   gr("分號連接對比句","分號連接兩個相關的獨立子句。","Young workers tend the brood and build wax comb; older ones graduate to foraging."),
   gr("not just in…","不只在…，也在…。","protecting bees calls for changes in farming, not just in beekeeping")],
  [q("What misconception does the writer correct?","That the queen controls the colony","That bees can dance","That workers are female"),
   q("How does the waggle dance show distance?","Through the length of each run","Through the color of the bee","Through the number of bees dancing"),
   q("What does the final paragraph suggest?","Saving bees requires changes in farming","Pesticides are the only problem","Beekeepers alone can solve the decline")]),
 L("The Limits of Recycling Plastic", "塑膠回收的極限", [
   "Few habits feel as virtuous as rinsing out a bottle and dropping it in the recycling bin. Yet the comforting image of an endless loop is largely an illusion: only a small fraction of all the plastic ever manufactured has actually been recycled, while the rest has been landfilled, incinerated or lost to the environment.",
   "The obstacles are partly chemical. Plastics are a family of very different materials, flagged by resin codes from one to seven, and they cannot simply be melted down together. Only a few, notably PET drinks bottles and HDPE containers, have reliable markets.",
   "Contamination compounds the problem. A single greasy food tray can spoil an entire bale, and even clean material tends to degrade with each round of processing. As a result, recycling often means downcycling into lower-grade products that will not be recycled again.",
   "None of this makes recycling pointless, but it does shift the emphasis. Many researchers now argue that the most effective strategies lie further upstream: designing products with fewer materials, expanding reuse systems and simply producing less plastic to begin with."],
  [w("virtuous","adjective","/ˈvɝː.tʃu.əs/","有美德的、正直的","morally good","She felt virtuous after the gym.","feel virtuous 覺得自己做了好事。"),
   w("illusion","noun","/ɪˈluː.ʒən/","錯覺、假象","an idea that is not true","Safety is an illusion.","largely an illusion 很大程度是假象。"),
   w("incinerate","verb","/ɪnˈsɪn.ə.reɪt/","焚化","to destroy by burning","The waste is incinerated.","被動 be incinerated。"),
   w("notably","adverb","/ˈnoʊ.t̬ə.bli/","尤其是","especially; used to give an important example","Several, notably Japan, agreed.","引出重要例子。"),
   w("compound","verb","/kəmˈpaʊnd/","使惡化","to make a problem worse","Rain compounded our difficulties.","compound the problem 使問題更糟。"),
   w("degrade","verb","/dɪˈɡreɪd/","降解、品質變差","to become worse in quality","Plastic degrades in sunlight.","degrade with each… 每次…就變差。"),
   w("downcycling","noun","/ˈdaʊnˌsaɪ.klɪŋ/","降級回收","recycling something into a lower-quality product","Downcycling is common for plastic.","down + recycling。"),
   w("upstream","adverb","/ʌpˈstriːm/","在上游、源頭","at an earlier stage of a process","Fix problems upstream.","further upstream 更源頭處。")],
  [gr("Few… as… as…","很少有…比…更…，強調最高程度。","Few habits feel as virtuous as rinsing out a bottle and dropping it in the recycling bin."),
   gr("None of this… but…","讓步：這不代表…，但…。","None of this makes recycling pointless, but it does shift the emphasis."),
   gr("強調助動詞 does","does + 原形動詞加強語氣。","but it does shift the emphasis")],
  [q("What does the writer call the idea of an endless recycling loop?","Largely an illusion","A proven success","A new technology"),
   q("Why can't all plastics be melted down together?","They are chemically very different","They are too heavy","They are all PET"),
   q("Where do researchers say the most effective solutions lie?","In reducing and redesigning before waste is made","In bigger recycling bins","In burning more plastic")]),
 L("The Case for Thirty-Day Experiments", "三十天實驗的道理", [
   "Matt Cutts, then an engineer at Google, opens his brief TED talk with a confession: he had fallen into a rut. Borrowing an idea from the filmmaker Morgan Spurlock, he resolved to try something new for 30 days, a span he considers long enough to form or break a habit without becoming daunting.",
   "The challenges themselves were modest at first, such as cycling to work or taking a photograph each day. What surprised him was the cumulative effect. Instead of blurring together, the months became distinct and memorable.",
   "As one experiment led to another, his confidence grew. He found himself climbing Mount Kilimanjaro and, during one November, writing a 50,000-word novel. He admits it was not a masterpiece, but finishing it still mattered to him.",
   "His most practical insight concerns scale. Ambitious, drastic changes can be fun, he notes, yet they rarely persist; small, sustainable ones are far more likely to endure. The talk closes by inviting viewers to identify something they have long wanted to try and simply commit to it for the next 30 days."],
  [w("confession","noun","/kənˈfeʃ.ən/","坦白","an admission that something is true, often embarrassing","I have a confession to make.","confess 的名詞。"),
   w("rut","noun","/rʌt/","一成不變的生活","a boring situation that is hard to change","stuck in a rut","fall into a rut 陷入一成不變。"),
   w("daunting","adjective","/ˈdɑːn.t̬ɪŋ/","令人怯步的","making you feel worried about being able to do it","a daunting task","without becoming daunting 不至於嚇人。"),
   w("cumulative","adjective","/ˈkjuː.mjə.lə.t̬ɪv/","累積的","increasing by adding over time","the cumulative effect","cumulative effect 累積效果。"),
   w("blur","verb","/blɝː/","變模糊","to become unclear and hard to separate","The days blurred together.","blur together 混成一團。"),
   w("masterpiece","noun","/ˈmæs.tɚ.piːs/","傑作","an excellent piece of work","a painting that is a masterpiece","not a masterpiece 不是傑作。"),
   w("drastic","adjective","/ˈdræs.tɪk/","劇烈的","extreme and sudden","drastic changes","drastic changes 激烈的改變。"),
   w("endure","verb","/ɪnˈdʊr/","持久","to continue to exist for a long time","Their friendship endured.","more likely to endure 更能持久。")],
  [gr("then + 職稱","then 表示「當時的」。","Matt Cutts, then an engineer at Google, opens his brief TED talk with a confession"),
   gr("What 名詞子句當主詞","What surprised him = 讓他驚訝的事。","What surprised him was the cumulative effect."),
   gr("find oneself + V-ing","發現自己（不知不覺）在做…。","He found himself climbing Mount Kilimanjaro")],
  [q("Why did Cutts choose 30 days?","It is long enough to change a habit but not overwhelming","It is the length of a TED talk","Google required it"),
   q("What was the unexpected result of his experiments?","The months became more distinct and memorable","He quit his job","He became a famous novelist"),
   q("What is his view of drastic changes?","They can be fun but rarely last","They are always better","They are impossible")]),
]
